class MemoryAugmentedModule {
private:
    JadeTensor memory;  // Külső memória slots
    JadeTensor query_proj;
    JadeTensor key_proj;
    JadeTensor value_proj;
    size_t num_slots;
    size_t slot_dim;

public:
    MemoryAugmentedModule(size_t slots, size_t dim, std::mt19937& gen)
        : num_slots(slots), slot_dim(dim),
          memory({slots, dim}),
          query_proj({dim, dim}),
          key_proj({dim, dim}),
          value_proj({dim, dim}) {

        memory.randomize(gen, 0.01);
        query_proj.randomize(gen, 0.02);
        key_proj.randomize(gen, 0.02);
        value_proj.randomize(gen, 0.02);
    }

    JadeTensor read(const JadeTensor& query_vec) {
        // Egyszerűsített tartalom-alapú olvasás
        JadeTensor result({slot_dim});
        result.fill(0.0);

        std::vector<double> scores(num_slots);
        double total = 0.0;

        for (size_t i = 0; i < num_slots; ++i) {
            double similarity = 0.0;
            for (size_t j = 0; j < slot_dim; ++j) {
                similarity += query_vec.at({j}) * memory.at({i, j});
            }
            scores[i] = std::exp(similarity / std::sqrt(slot_dim));
            total += scores[i];
        }

        // Weighted sum
        for (size_t i = 0; i < num_slots; ++i) {
            double weight = scores[i] / (total + 1e-8);
            for (size_t j = 0; j < slot_dim; ++j) {
                result.at({j}) += weight * memory.at({i, j});
            }
        }

        return result;
    }

    void write(const JadeTensor& value_vec, size_t slot_idx) {
        if (slot_idx < num_slots) {
            for (size_t i = 0; i < slot_dim; ++i) {
                memory.at({slot_idx, i}) = value_vec.at({i});
            }
        }
    }
};

