class JadeModel {
private:
    JadeConfig config;
    JadeTokenizer tokenizer;
    std::mt19937 generator;

    JadeTensor embedding_matrix;
    std::vector<HierarchicalSSM> ssm_layers;
    std::vector<SparseMoELayer> moe_layers;
    std::vector<MemoryAugmentedModule> memory_modules;
    JadeTensor output_projection;

public:
    JadeModel(const JadeConfig& cfg)
        : config(cfg), tokenizer(cfg.vocabulary_size), generator(cfg.seed),
          embedding_matrix({cfg.vocabulary_size, cfg.embedding_dim}),
          output_projection({cfg.vocabulary_size, cfg.embedding_dim}) {

        std::cout << "Jade Neural inicializálás...\n";
        std::cout << "  Kontextus hossz: " << cfg.max_context_length << " token\n";
        std::cout << "  Rétegek: " << cfg.num_expert_layers << "\n";
        std::cout << "  Expertek/réteg: " << cfg.experts_per_layer << "\n";

        // Embedding inicializálás
        embedding_matrix.randomize(generator, 0.02);
        output_projection.randomize(generator, 0.02);

        // Rétegek építése
        for (size_t i = 0; i < cfg.num_expert_layers; ++i) {
            ssm_layers.emplace_back(cfg.state_space_dim, cfg.embedding_dim, generator);
            moe_layers.emplace_back(cfg.experts_per_layer, cfg.embedding_dim, 
                                   cfg.embedding_dim, 2, generator);
            memory_modules.emplace_back(cfg.memory_slots, cfg.embedding_dim, generator);
        }

        std::cout << "Jade Neural inicializálva!\n";
    }

    JadeTensor get_embedding(size_t token_id) {
        JadeTensor emb({config.embedding_dim});
        for (size_t i = 0; i < config.embedding_dim; ++i) {
            emb.at({i}) = embedding_matrix.at({token_id % config.vocabulary_size, i});
        }
        return emb;
    }

    JadeTensor forward_layer(size_t layer_idx, const JadeTensor& input) {
        // 1. State Space Model (hosszú kontextus kezelés)
        JadeTensor ssm_out = ssm_layers[layer_idx].forward(input);

        // 2. Sparse Mixture of Experts
        JadeTensor moe_out = moe_layers[layer_idx].forward(ssm_out);

        // 3. Memory Augmentation
        JadeTensor mem_read = memory_modules[layer_idx].read(moe_out);

        // 4. Residual connection
        JadeTensor output({config.embedding_dim});
        for (size_t i = 0; i < config.embedding_dim; ++i) {
            output.at({i}) = input.at({i}) + moe_out.at({i}) + 0.1 * mem_read.at({i});
        }

        return output;
    }

    std::vector<double> predict_next_token(const std::vector<size_t>& tokens) {
        if (tokens.empty()) {
            return std::vector<double>(config.vocabulary_size, 1.0 / config.vocabulary_size);
        }

        // Utolsó token embedding
        size_t last_token = tokens.back();
        JadeTensor current = get_embedding(last_token);

        // Összes rétegen keresztül
        for (size_t i = 0; i < config.num_expert_layers; ++i) {
            current = forward_layer(i, current);
        }

        // Output projection
        std::vector<double> logits(config.vocabulary_size, 0.0);
        for (size_t i = 0; i < config.vocabulary_size; ++i) {
            for (size_t j = 0; j < config.embedding_dim; ++j) {
                logits[i] += output_projection.at({i, j}) * current.at({j});
            }
        }

        // Softmax
        double max_logit = *std::max_element(logits.begin(), logits.end());
        double sum_exp = 0.0;
        for (auto& l : logits) {
            l = std::exp(l - max_logit);
            sum_exp += l;
        }
        for (auto& l : logits) l /= sum_exp;

        return logits;
    }

    std::string generate(const std::string& prompt, size_t max_new_tokens = 50) {
        std::vector<size_t> tokens = tokenizer.encode(prompt);

        for (size_t i = 0; i < max_new_tokens; ++i) {
            std::vector<double> probs = predict_next_token(tokens);

            // Top-p (nucleus) sampling
            std::vector<size_t> indices(probs.size());
            std::iota(indices.begin(), indices.end(), 0);
            std::sort(indices.begin(), indices.end(),
                [&](size_t a, size_t b) { return probs[a] > probs[b]; });

            // Válassz a top 10-ből
            std::uniform_int_distribution<size_t> dist(0, std::min(size_t(9), probs.size() - 1));
            size_t next_token = indices[dist(generator)];

            tokens.push_back(next_token);

            if (next_token == 3) break; // EOS
        }

        return tokenizer.decode(tokens);
    }

    void reset_memory() {
        for (auto& ssm : ssm_layers) {
            ssm.reset_state();
        }
    }
};

